const rateLimit = (windowMs = 60_000, max = 120) => (req, res, next) => {
  const key = `${req.ip}:${req.path}`;
  const current = requestCounts.get(key) || { count: 0, resetAt: Date.now() + windowMs };
  if (Date.now() > current.resetAt) { current.count = 0; current.resetAt = Date.now() + windowMs; }
  current.count += 1; requestCounts.set(key, current);
  if (current.count > max) return res.status(429).json({ error: 'Too many requests. Please try again shortly.' });
  next();
};
