const supabaseAuth = async (req, res, next) => { try { const accessToken = (req.headers.authorization || '').replace('Bearer ', ''); if (!accessToken) return res.status(401).json({ error: 'Authentication required' }); const identity = await authUser(accessToken); const profiles = await query('profiles', `?id=eq.${encodeURIComponent(identity.id)}&select=id,full_name,email,role,phone,active`); const profile = profiles?.[0]; if (!profile || profile.active === false) return res.status(403).json({ error: 'Authenticated account has no active SkyFlow profile' }); req.user = { id: identity.id, role: profile.role, name: profile.full_name, email: profile.email }; next(); } catch { res.status(401).json({ error: 'Authentication required' }); } };
const auth = (req, res, next) => { if (supabaseConfigured) return supabaseAuth(req, res, next); try { const verified = jwt.verify((req.headers.authorization || '').replace('Bearer ', ''), process.env.JWT_SECRET || 'skyflow-dev-secret'); const user = db.users.find(item => item.id === verified.id); if (!user || user.active === false) return res.status(401).json({ error: 'Account is inactive or no longer exists' }); req.user = { ...verified, role: user.role, name: user.name }; next(); } catch { res.status(401).json({ error: 'Authentication required' }); } };
const allow = (...roles) => (req, res, next) => roles.includes(req.user.role) || roles.some(role => permissions[req.user.role]?.includes(role)) ? next() : res.status(403).json({ error: 'Insufficient permission' });
const publicFlight = f => { const origin = smart?.airports?.find(a => a.code === f.origin); const destination = smart?.airports?.find(a => a.code === f.destination); return { ...f, flightNumber: f.number, departureTime: f.scheduled, arrivalTime: f.arrival, availableSeats: f.seats - f.booked, available: f.seats - f.booked, originAirport: origin, destinationAirport: destination, stopsLabel: f.stops === 0 ? 'Non-stop' : `${f.stops} stop(s)` }; };
