const airportFor = term => smart.airports.find(a => a.code.toLowerCase() === String(term || '').trim().toLowerCase());
const airportCodeForQuery = term => { const value = String(term || '').trim().toLowerCase(); return smart.airports.find(a => [a.code, a.name, a.city].some(candidate => candidate.toLowerCase() === value))?.code || String(term || '').trim().toUpperCase(); };
