const normalizeFlight = input => ({ number: String(input.number || input.flightNumber || '').trim(), airlineCode: String(input.airlineCode || 'SFA').trim().toUpperCase(), airline: String(input.airline || db.airlines.find(a => a.code === String(input.airlineCode || 'SFA').toUpperCase())?.name || '').trim(), origin: String(input.origin || '').trim().toUpperCase(), destination: String(input.destination || '').trim().toUpperCase(), date: String(input.date || '').trim(), scheduled: String(input.scheduled || input.departureTime || '').trim(), arrival: String(input.arrival || input.arrivalTime || '').trim(), durationMinutes: Number(input.durationMinutes || 0), stops: Number(input.stops || 0), travelClass: String(input.travelClass || 'Economy'), fare: Number(input.fare || 0), baggageAllowance: String(input.baggageAllowance || '20 kg'), estimated: String(input.estimated || input.scheduled || '').trim(), terminal: String(input.terminal || '').trim(), gate: String(input.gate || '').trim(), status: String(input.status || 'Scheduled'), aircraft: String(input.aircraft || '').trim(), seats: Number(input.seats || input.seatCapacity || 0), booked: Number(input.booked || 0) });
