app.patch('/api/settings',auth,allow('settings'),async(req,res,next)=>{if(!supabaseConfigured)return next();const valid={};for(const key of ['cancellationWindowHours','checkInWindowHours'])if(req.body?.[key]!==undefined){const value=Number(req.body[key]);if(!Number.isFinite(value)||value<0||value>720)return res.status(400).json({error:`${key} must be between 0 and 720`});valid[key]=value;}if(!Object.keys(valid).length)return res.status(400).json({error:'No valid settings supplied'});try{const prior=(await query('system_settings','?key=eq.operational_rules&select=value&limit=1'))[0]?.value||{};const value={...prior,...valid};await upsert('system_settings',{key:'operational_rules',value,updated_by:req.user.id,updated_at:new Date().toISOString()},'key');await insert('audit_logs',{actor_id:req.user.id,action:'settings.updated',entity_type:'system_settings',metadata:value});res.json({data:value});}catch(error){repositoryFailure(res,error);}});
