app.patch('/api/bookings/:id/status', auth, allow('admin'), async (req, res, next) => { if (!supabaseConfigured) return next(); const status = String(req.body?.status || ''); if (!['Confirmed','Checked-in','Cancelled','Completed','Refund pending','Refunded'].includes(status)) return res.status(400).json({ error: 'Unsupported booking status' }); try { const current = await getPersistentBooking(req.params.id, { ...req.user, role: 'super-admin' }); if (!current) return res.status(404).json({ error: 'Booking not found' }); const changes={ status, changed_by:req.user.id, updated_at:new Date().toISOString() }; if(status==='Cancelled')changes.cancelled_at=new Date().toISOString(); const rows = await update('bookings', `id=eq.${encodeURIComponent(req.params.id)}`, changes); res.json({ data: rows?.[0] || { ...current, status } }); } catch (error) { repositoryFailure(res, error); } });
app.patch('/api/bookings/:id/baggage', auth, allow('admin'), async (req, res, next) => { if (!supabaseConfigured) return next(); const status = String(req.body?.status || '').trim(); if (!['Baggage Accepted','In Transit','Loaded','Arrived','Delayed','Missing','Delivered'].includes(status)) return res.status(400).json({ error: 'Unsupported baggage status' }); try { const baggageRows = await query('baggage', `?booking_id=eq.${encodeURIComponent(req.params.id)}&select=id,status,tag_number&limit=1`); const baggage = baggageRows[0]; if (!baggage) return res.status(404).json({ error: 'Baggage record not found' }); const updatedRows = await update('baggage', `id=eq.${encodeURIComponent(baggage.id)}`, { status, changed_by:req.user.id, updated_at: new Date().toISOString() }); res.json({ data: { ...updatedRows[0], tag_number: baggage.tag_number }, simulated: true }); } catch (error) { repositoryFailure(res, error); } });
app.get('/api/me', auth, async (req, res, next) => { if (!supabaseConfigured) return next(); try { const [profileRows, bookings, notifications] = await Promise.all([query('profiles', `?id=eq.${encodeURIComponent(req.user.id)}&select=id,full_name,email,role,phone`), listPersistentBookings(req.user), query('notifications', `?user_id=eq.${encodeURIComponent(req.user.id)}&select=id,title,body,read_at,created_at&order=created_at.desc&limit=100`)]); const profile = profileRows[0]; res.json({ user: profile ? { id: profile.id, name: profile.full_name, email: profile.email, role: profile.role, phone: profile.phone } : null, bookings, notifications: notifications.map(item => ({ id: item.id, title: item.title, body: item.body, read: Boolean(item.read_at), time: item.created_at })) }); } catch (error) { repositoryFailure(res, error); } });
const passwordHash = value => crypto.createHash('sha256').update(String(value)).digest('hex');
const passwordMatches = (user, value) => user.passwordHash ? crypto.timingSafeEqual(Buffer.from(user.passwordHash, 'hex'), Buffer.from(passwordHash(value), 'hex')) : user.password === value;
app.post('/api/auth/login', rateLimit(60_000, 30), async (req, res, next) => { if (!supabaseConfigured) return next(); const { email, password } = req.body || {}; if (!email || !password || !/^\S+@\S+\.\S+$/.test(String(email))) return res.status(400).json({ error: 'Valid email and password are required' }); try { const session = await authPasswordGrant(String(email).toLowerCase(), password); const profiles = await query('profiles', `?id=eq.${encodeURIComponent(session.user.id)}&select=id,full_name,email,role,phone,active`); const profile = profiles?.[0]; if (!profile || profile.active === false) return res.status(403).json({ error: 'Authenticated account is not active in SkyFlow' }); res.json({ token: session.access_token, refreshToken: session.refresh_token, expiresIn: session.expires_in, user: { id: profile.id, name: profile.full_name, email: profile.email, role: profile.role, emailVerified: Boolean(session.user.email_confirmed_at) } }); } catch { res.status(401).json({ error: 'Invalid credentials' }); } });
app.post('/api/auth/refresh', rateLimit(60_000, 60), async (req, res) => { if (!supabaseConfigured) return res.status(503).json({ error: 'Supabase Auth is not configured' }); const refreshToken = String(req.body?.refreshToken || ''); if (!refreshToken) return res.status(400).json({ error: 'Refresh token is required' }); try { const session = await authRefreshToken(refreshToken); const profiles = await query('profiles', `?id=eq.${encodeURIComponent(session.user.id)}&select=id,full_name,email,role,active`); const profile = profiles?.[0]; if (!profile || profile.active === false) return res.status(403).json({ error: 'Account is not active' }); res.json({ token: session.access_token, refreshToken: session.refresh_token, expiresIn: session.expires_in, user: { id: profile.id, name: profile.full_name, email: profile.email, role: profile.role, emailVerified: Boolean(session.user.email_confirmed_at) } }); } catch { res.status(401).json({ error: 'Session expired. Please sign in again.' }); } });
app.post('/api/auth/logout', auth, async (req, res) => { if (supabaseConfigured) { try { await authLogout((req.headers.authorization || '').replace('Bearer ', '')); } catch { /* Clear local client session even if provider logout is unreachable. */ } } res.json({ ok: true }); });
app.post('/api/auth/change-password', auth, rateLimit(60_000, 5), async (req, res) => { const password = String(req.body?.password || ''); if (password.length < 12) return res.status(400).json({ error: 'New password must be at least 12 characters' }); if (!supabaseConfigured) return res.status(503).json({ error: 'Password changes require Supabase Auth' }); try { const token = (req.headers.authorization || '').replace('Bearer ', ''); await authUpdatePassword(token, password); await insert('audit_logs', { actor_id: req.user.id, action: 'auth.password_changed', entity_type: 'profile', entity_id: req.user.id, metadata: {} }); res.json({ ok: true, message: 'Password updated. Other sessions may need to sign in again.' }); } catch { res.status(503).json({ error: 'Password update failed. Please retry.' }); } });
