app.post('/api/auth/login', rateLimit(60_000, 30), (req, res) => { if (!demoMode) return res.status(503).json({ error: 'Supabase Auth is required. Configure Supabase credentials before signing in.' }); const { email, password } = req.body || {}; if (!email || !password || !/^\S+@\S+\.\S+$/.test(String(email))) return res.status(400).json({ error: 'Valid email and password are required' }); const user = db.users.find(u => u.email.toLowerCase() === String(email).toLowerCase()); if (!user || !passwordMatches(user, password) || user.active === false) return res.status(401).json({ error: 'Invalid credentials' }); res.json({ token: token(user), user: { id: user.id, name: user.name, email: user.email, role: user.role, emailVerified: user.emailVerified !== false } }); });
app.get('/api/airports', (req, res) => { const q = String(req.query.q || '').trim(); const data = smart.airports.filter(a => airportMatches(a, q)); res.json({ data, count: data.length, simulated: true }); });
app.get('/api/airlines', (_, res) => res.json({ data: db.airlines }));
app.get('/api/flights', (req, res) => { const { origin, destination, date, airline, maxPrice, departureAfter, departureBefore, stops, travelClass, sort = 'earliest' } = req.query; const originCode = airportCodeForQuery(origin); const destinationCode = airportCodeForQuery(destination); if (origin && destination && originCode === destinationCode) return res.status(400).json({ error: 'Origin and destination must be different' }); let data = db.flights.filter(f => (!origin || f.origin === originCode) && (!destination || f.destination === destinationCode) && (!date || f.date === date) && (!airline || f.airlineCode === airline || f.airline === airline) && (!maxPrice || f.fare <= Number(maxPrice)) && (!departureAfter || f.scheduled >= departureAfter) && (!departureBefore || f.scheduled <= departureBefore) && (!stops || (stops === 'nonstop' ? f.stops === 0 : f.stops > 0)) && (!travelClass || f.travelClass === travelClass)); data = [...data].sort((a,b) => sort === 'cheapest' ? a.fare - b.fare : sort === 'fastest' ? a.durationMinutes - b.durationMinutes : a.scheduled.localeCompare(b.scheduled)); res.json({ data: data.map(publicFlight), count: data.length, updatedAt: new Date().toISOString(), simulated: true }); });
app.get('/api/dashboard', auth, allow('admin'), (_, res) => { const stats = { passengers: db.users.filter(user => user.role === 'passenger').length, departures: db.flights.filter(flight => flight.date && flight.status !== 'Cancelled').length, arrivals: db.flights.filter(flight => flight.date && flight.status !== 'Cancelled').length, activeFlights: db.flights.filter(flight => !['Cancelled','Departed','Completed'].includes(flight.status)).length, delayed: db.flights.filter(flight => flight.status === 'Delayed').length, bookings: db.bookings.length, availableGates: operational?.gates?.filter(gate => gate.status === 'Available').length || 0, staffOnDuty: operational?.staff?.filter(staff => staff.active !== false).length || 0, revenue: db.payments.filter(payment => payment.status === 'Completed').reduce((sum, payment) => sum + Number(payment.amount || 0), 0) }; res.json({ stats, recentBookings: db.bookings.slice(-20).reverse(), alerts: db.flights.filter(flight => ['Delayed','Cancelled'].includes(flight.status)).map(flight => ({ title: `${flight.number} ${flight.status.toLowerCase()}`, body: `Terminal ${flight.terminal}, gate ${flight.gate || 'TBC'}`, level: flight.status === 'Delayed' ? 'warning' : 'error' })) }); });
