const publicUser = user => ({ id: user.id, name: user.name, email: user.email, role: user.role, phone: user.phone || '', active: user.active !== false, emailVerified: user.emailVerified !== false });
const adminRoles = ['super-admin', 'airport-admin', 'operations-manager', 'check-in-staff', 'gate-staff', 'security-staff'];

app.post('/api/auth/register', rateLimit(60_000, 5), async (req, res, next) => { if (!supabaseConfigured) return next(); const name = String(req.body?.name || '').trim(); const email = String(req.body?.email || '').trim().toLowerCase(); const password = String(req.body?.password || ''); if (name.length < 2 || !/^\S+@\S+\.\S+$/.test(email) || password.length < 12) return res.status(400).json({ error: 'Name, valid email and a password of at least 12 characters are required' }); try { const identity = await authSignUp(email, password, { full_name: name, role: 'passenger' }); const identityId = identity.user?.id || identity.id; const profile = (await query('profiles', `?id=eq.${encodeURIComponent(identityId)}&select=id,full_name,email,role,phone,active`))[0]; if (!profile) return res.status(502).json({ error: 'Account was created but its profile is not available. Contact support.' }); res.status(201).json({ user: publicUser({ ...profile, name: profile.full_name, active: profile.active !== false, emailVerified: false }), verificationRequired: true, message: 'Account created. Check the verification email from Supabase Auth.' }); } catch (error) { res.status(error.status === 422 ? 409 : 502).json({ error: error.status === 422 ? 'An account with this email already exists' : 'Authentication provider unavailable' }); } });
app.post('/api/auth/register', rateLimit(60_000, 5), (req, res) => { if (!demoMode) return res.status(503).json({ error: 'Supabase Auth is required. Configure Supabase credentials before registering.' }); const name = String(req.body?.name || '').trim(); const email = String(req.body?.email || '').trim().toLowerCase(); const password = String(req.body?.password || ''); if (name.length < 2 || !/^\S+@\S+\.\S+$/.test(email) || password.length < 8) return res.status(400).json({ error: 'Name, valid email and a password of at least 8 characters are required' }); if (db.users.some(user => user.email.toLowerCase() === email)) return res.status(409).json({ error: 'An account with this email already exists' }); const user = { id: `u-${crypto.randomUUID()}`, name, email, role: 'passenger', passwordHash: passwordHash(password), active: true, emailVerified: false, createdAt: new Date().toISOString() }; db.users.push(user); res.status(201).json({ user: publicUser(user), verificationRequired: true, message: 'Demo account created. Configure Supabase Auth for real email verification.' }); });
app.post('/api/auth/forgot-password', rateLimit(60_000, 5), async (req, res) => { if (supabaseConfigured) { try { await authResetPassword(String(req.body?.email || '').trim().toLowerCase()); } catch { /* Keep reset responses neutral to avoid account enumeration. */ } return res.json({ ok: true, message: 'If the account exists, Supabase Auth has been asked to send reset instructions.', simulated: false }); } if(!demoMode)return res.status(503).json({error:'Password recovery requires configured Supabase Auth and email delivery'}); res.json({ ok: true, message: 'Password recovery is unavailable in local test demo mode.', simulated: true }); });
app.get('/api/profile', auth, async (req, res, next) => { if (!supabaseConfigured) return next(); try { const rows = await query('profiles', `?id=eq.${encodeURIComponent(req.user.id)}&select=id,full_name,email,role,phone`); const profile = rows?.[0]; if (!profile) return res.status(404).json({ error: 'Profile not found' }); res.json({ data: publicUser({ ...profile, name: profile.full_name, active: true, emailVerified: true }) }); } catch { res.status(503).json({ error: 'Profile service unavailable' }); } });
app.get('/api/profile', auth, (req, res) => { const user = db.users.find(item => item.id === req.user.id); res.json({ data: publicUser(user) }); });
app.patch('/api/profile', auth, async (req, res, next) => { if (!supabaseConfigured) return next(); const name = String(req.body?.name || '').trim(); const phone = String(req.body?.phone || '').trim(); if (name.length < 2 || phone.length > 30) return res.status(400).json({ error: 'Profile values are invalid' }); try { const rows = await update('profiles', `id=eq.${encodeURIComponent(req.user.id)}`, { full_name: name, phone }); const profile = rows?.[0]; res.json({ data: publicUser({ ...profile, name: profile.full_name, active: true, emailVerified: true }) }); } catch { res.status(503).json({ error: 'Profile service unavailable' }); } });
app.patch('/api/profile', auth, (req, res) => { const user = db.users.find(item => item.id === req.user.id); const name = String(req.body?.name ?? user.name).trim(); const phone = String(req.body?.phone ?? user.phone ?? '').trim(); if (name.length < 2 || phone.length > 30) return res.status(400).json({ error: 'Profile values are invalid' }); user.name = name; user.phone = phone; audit(req, 'profile.updated', 'profile', user.id); res.json({ data: publicUser(user) }); });
app.post('/api/profile/deactivate', auth, (req, res) => { const user = db.users.find(item => item.id === req.user.id); user.active = false; audit(req, 'profile.deactivated', 'profile', user.id); res.json({ ok: true }); });

app.get('/api/admin/users', auth, allow('admin'), (req, res) => { const query = String(req.query.q || '').toLowerCase(); const data = db.users.filter(user => adminRoles.includes(user.role) && (!query || `${user.name} ${user.email} ${user.role}`.toLowerCase().includes(query))).map(publicUser); res.json({ data, count: data.length }); });
app.post('/api/admin/users', auth, allow('super-admin'), (req, res) => { const { name, email, role = 'airport-admin' } = req.body || {}; if (!name || !/^\S+@\S+\.\S+$/.test(String(email || '')) || !adminRoles.includes(role) || role === 'super-admin' && req.user.role !== 'super-admin') return res.status(400).json({ error: 'Valid name, email and approved administrator role are required' }); if (db.users.some(user => user.email.toLowerCase() === String(email).toLowerCase())) return res.status(409).json({ error: 'Email is already in use' }); const user = { id: `u-${crypto.randomUUID()}`, name: String(name).trim(), email: String(email).toLowerCase(), role, active: true, emailVerified: false, invitedAt: new Date().toISOString() }; db.users.push(user); const invitation = { id: crypto.randomUUID(), userId: user.id, email: user.email, status: 'Pending setup', createdAt: new Date().toISOString() }; operational.adminInvitations.push(invitation); audit(req, 'admin.invited', 'user', user.id, { role }); res.status(201).json({ data: publicUser(user), invitation, message: 'Invitation recorded. Configure Supabase Auth email delivery to send the setup link.' }); });
app.patch('/api/admin/users/:id', auth, allow('super-admin'), (req, res) => { const user = db.users.find(item => item.id === req.params.id && adminRoles.includes(item.role)); if (!user) return res.status(404).json({ error: 'Administrator not found' }); const nextRole = req.body?.role || user.role; if (!adminRoles.includes(nextRole)) return res.status(400).json({ error: 'Unsupported administrator role' }); if (user.role === 'super-admin' && nextRole !== 'super-admin' && db.users.filter(item => item.role === 'super-admin' && item.active !== false).length < 2) return res.status(409).json({ error: 'The last active Super Administrator cannot be demoted' }); user.role = nextRole; if (typeof req.body?.active === 'boolean') user.active = req.body.active; audit(req, 'admin.updated', 'user', user.id, { role: user.role, active: user.active }); res.json({ data: publicUser(user) }); });

app.get('/api/operations/gates', auth, allow('operations'), (req, res) => res.json({ data: operational.gates }));
app.get('/api/operations/runways', auth, allow('operations'), (req, res) => res.json({ data: operational.runways }));
app.patch('/api/operations/runways/:id', auth, allow('operations'), (req, res) => { const runway = operational.runways.find(item => item.id === req.params.id); if (!runway) return res.status(404).json({ error: 'Runway not found' }); if (!['Operational', 'Maintenance', 'Closed'].includes(req.body?.status)) return res.status(400).json({ error: 'Unsupported runway status' }); runway.status = req.body.status; audit(req, 'runway.status.updated', 'runway', runway.id, { status: runway.status }); res.json({ data: runway }); });
app.get('/api/support/tickets', auth, (req, res) => res.json({ data: operational.supportTickets.filter(item => req.user.role !== 'passenger' || item.userId === req.user.id) }));
app.post('/api/support/tickets', auth, (req, res) => { const subject = String(req.body?.subject || '').trim(); const description = String(req.body?.description || '').trim(); if (subject.length < 3 || description.length < 5) return res.status(400).json({ error: 'A subject and description are required' }); const item = { id: `st-${crypto.randomUUID()}`, userId: req.user.id, subject, description, priority: 'Normal', status: 'Open', createdAt: new Date().toISOString() }; operational.supportTickets.push(item); audit(req, 'support.created', 'support_ticket', item.id); res.status(201).json({ data: item }); });
app.patch('/api/support/tickets/:id', auth, allow('admin'), (req, res) => { const item = operational.supportTickets.find(ticket => ticket.id === req.params.id); if (!item) return res.status(404).json({ error: 'Support ticket not found' }); if (req.body?.status && !['Open', 'In progress', 'Resolved', 'Closed'].includes(req.body.status)) return res.status(400).json({ error: 'Unsupported ticket status' }); Object.assign(item, pick(req.body, ['status', 'priority', 'assignedTo'])); audit(req, 'support.updated', 'support_ticket', item.id, { status: item.status }); res.json({ data: item }); });
app.get('/api/announcements', auth, (_, res) => res.json({ data: operational.announcements.filter(item => item.status === 'Published') }));
app.post('/api/announcements', auth, allow('admin'), (req, res) => { const title = String(req.body?.title || '').trim(); const body = String(req.body?.body || '').trim(); if (title.length < 3 || body.length < 5) return res.status(400).json({ error: 'Announcement title and body are required' }); const item = { id: `an-${crypto.randomUUID()}`, title, body, status: 'Published', createdBy: req.user.id, createdAt: new Date().toISOString() }; operational.announcements.push(item); audit(req, 'announcement.published', 'announcement', item.id); res.status(201).json({ data: item }); });
app.get('/api/reports/summary', auth, allow('reports'), (req, res) => { const data = { flights: db.flights.length, cancelledFlights: db.flights.filter(item => item.status === 'Cancelled').length, bookings: db.bookings.length, checkedIn: db.bookings.filter(item => item.checkedIn).length, passengers: db.users.filter(item => item.role === 'passenger').length, supportOpen: operational.supportTickets.filter(item => item.status !== 'Closed').length, delayedFlights: db.flights.filter(item => item.status === 'Delayed').length, simulatedRevenue: db.payments.filter(item => item.status === 'Completed').reduce((sum, item) => sum + Number(item.amount || 0), 0) }; res.json({ data, period: { from: req.query.from || null, to: req.query.to || null }, simulatedRevenue: true }); });
app.get('/api/audit-logs', auth, allow('admin'), (req, res) => res.json({ data: operational.auditLogs.slice(-200).reverse() }));
app.get('/api/settings', auth, allow('settings'), (_, res) => res.json({ data: operational.settings, simulated: true }));
app.patch('/api/settings', auth, allow('settings'), (req, res) => { for (const key of ['cancellationWindowHours', 'checkInWindowHours']) if (req.body?.[key] !== undefined && Number.isFinite(Number(req.body[key])) && Number(req.body[key]) >= 0) operational.settings[key] = Number(req.body[key]); audit(req, 'settings.updated', 'settings', 'system', operational.settings); res.json({ data: operational.settings }); });

app.post('/api/operations/check-in/:bookingId', auth, allow('check-in'), (req, res) => { const booking = db.bookings.find(item => item.id === req.params.bookingId); if (!booking) return res.status(404).json({ error: 'Booking not found' }); if (booking.status === 'Cancelled' || booking.status === 'Completed') return res.status(409).json({ error: 'Booking is not eligible for check-in' }); if (booking.checkedIn) return res.status(409).json({ error: 'Booking is already checked in' }); booking.checkedIn = true; booking.status = 'Checked-in'; audit(req, 'check-in.completed', 'booking', booking.id); res.json({ data: booking, boardingPass: { reference: `BP-${booking.pnr}`, qr: `SKYFLOW:${booking.pnr}` }, simulated: true }); });
app.post('/api/operations/boarding/:bookingId', auth, allow('boarding'), (req, res) => { const booking = db.bookings.find(item => item.id === req.params.bookingId); if (!booking) return res.status(404).json({ error: 'Booking not found' }); if (!booking.checkedIn) return res.status(409).json({ error: 'Passenger must be checked in before boarding' }); if (operational.boarding.some(item => item.bookingId === booking.id)) return res.status(409).json({ error: 'Boarding has already been recorded' }); const record = { id: crypto.randomUUID(), bookingId: booking.id, status: 'Boarded', actorId: req.user.id, boardedAt: new Date().toISOString() }; operational.boarding.push(record); booking.status = 'Completed'; audit(req, 'boarding.completed', 'booking', booking.id); res.status(201).json({ data: record, booking }); });
app.get('/api/operations/screenings', auth, allow('security'), (req, res) => res.json({ data: operational.screenings }));
app.post('/api/operations/screenings', auth, allow('security'), (req, res) => { const booking = db.bookings.find(item => item.id === req.body?.bookingId); if (!booking) return res.status(404).json({ error: 'Booking not found' }); const existing = operational.screenings.find(item => item.bookingId === booking.id && item.status === 'Cleared'); if (existing) return res.status(409).json({ error: 'Screening is already cleared' }); const record = { id: crypto.randomUUID(), bookingId: booking.id, status: ['Cleared','Referred','Pending'].includes(req.body?.status) ? req.body.status : 'Pending', notes: String(req.body?.notes || '').slice(0, 500), actorId: req.user.id, createdAt: new Date().toISOString() }; operational.screenings.push(record); audit(req, 'screening.recorded', 'screening', record.id, { status: record.status }); res.status(201).json({ data: record, simulated: true }); });


// Passenger service request centre: one shared workflow for passenger submissions and admin operations.
const SERVICE_REQUEST_TYPES = new Set([
  'Hotel booking','Airport taxi','Parking reservation','Dining order','Shopping assistance',
  'Wheelchair assistance','Elderly passenger assistance','Medical assistance','Unaccompanied minor support',
  'Hearing assistance','Visual assistance','Lost baggage','Delayed baggage','Baggage delivery',
  'Special meal request','Lounge access','Porter service','Language assistance','Airport escort',
  'Pet travel assistance','Accessibility support','Travel document help','Flight disruption support',
  'Refund request','Booking change','Passenger complaint','Service feedback','Lost and found',
  'Airport shuttle','General support'
]);
const serviceRequestStatus = new Set(['Submitted','Acknowledged','In progress','Waiting for passenger','Resolved','Rejected']);
const serviceRequestPriority = new Set(['Low','Normal','High','Urgent']);

app.get('/api/service-requests', auth, async (req, res, next) => {
  if (!supabaseConfigured) {
    const rows = db.serviceRequests
      .filter(item => req.user.role === 'passenger' ? item.userId === req.user.id : true)
      .sort((a,b) => new Date(b.createdAt) - new Date(a.createdAt));
    return res.json({ data: rows, simulated: true });
  }
  try {
    const filters = ['select=id,user_id,request_type,title,description,location,details,status,priority,admin_response,assigned_to,created_at,updated_at','order=created_at.desc','limit=500'];
    if (req.user.role === 'passenger') filters.push(`user_id=eq.${encodeURIComponent(req.user.id)}`);
    const rows = await query('passenger_service_requests', `?${filters.join('&')}`);
    const ids = [...new Set(rows.map(row => row.user_id))];
    const profiles = ids.length ? await query('profiles', `?select=id,full_name,email&id=in.(${ids.map(encodeURIComponent).join(',')})`) : [];
    const profileMap = new Map(profiles.map(profile => [profile.id, profile]));
    res.json({ data: rows.map(row => ({ ...row, passenger_name: profileMap.get(row.user_id)?.full_name || 'Passenger', passenger_email: profileMap.get(row.user_id)?.email || '' })), simulated: false });
  } catch (error) { repositoryFailure(res, error); }
});

app.post('/api/service-requests', auth, allow('passenger'), async (req, res, next) => {
  if (req.user.role !== 'passenger') return res.status(403).json({ error: 'Only passenger accounts can submit passenger service requests.' });
  const requestType = String(req.body?.requestType || '').trim();
  const title = String(req.body?.title || requestType).trim().slice(0, 120);
  const description = String(req.body?.description || '').trim().slice(0, 3000);
  const location = String(req.body?.location || '').trim().slice(0, 160);
  if (!SERVICE_REQUEST_TYPES.has(requestType)) return res.status(400).json({ error: 'Choose a supported passenger service.' });
  if (title.length < 3 || description.length < 8) return res.status(400).json({ error: 'Add a clear title and at least 8 characters of details.' });
  const details = req.body?.details && typeof req.body.details === 'object' ? req.body.details : {};
  if (!supabaseConfigured) {
    const row = { id: crypto.randomUUID(), userId: req.user.id, passenger_name: req.user.name, passenger_email: req.user.email || '', request_type: requestType, title, description, location, details, status: 'Submitted', priority: requestType === 'Medical assistance' ? 'Urgent' : 'Normal', admin_response: '', assigned_to: null, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), simulated: true };
    db.serviceRequests.unshift(row);
    return res.status(201).json({ data: row, simulated: true });
  }
  try {
    const row = (await insert('passenger_service_requests', { user_id: req.user.id, request_type: requestType, title, description, location: location || null, details, status: 'Submitted', priority: requestType === 'Medical assistance' ? 'Urgent' : 'Normal' }))[0];
    res.status(201).json({ data: row, simulated: false });
  } catch (error) { repositoryFailure(res, error); }
});

app.patch('/api/service-requests/:id', auth, allow('admin'), async (req, res, next) => {
  const changes = {};
  if (req.body?.status !== undefined) {
    if (!serviceRequestStatus.has(req.body.status)) return res.status(400).json({ error: 'Unsupported request status.' });
    changes.status = req.body.status;
  }
  if (req.body?.priority !== undefined) {
    if (!serviceRequestPriority.has(req.body.priority)) return res.status(400).json({ error: 'Unsupported priority.' });
    changes.priority = req.body.priority;
  }
  if (req.body?.adminResponse !== undefined) changes.admin_response = String(req.body.adminResponse).trim().slice(0, 2000);
  if (req.body?.assignedTo !== undefined) changes.assigned_to = req.body.assignedTo || null;
  if (!Object.keys(changes).length) return res.status(400).json({ error: 'No supported changes supplied.' });
  changes.updated_at = new Date().toISOString();
  if (!supabaseConfigured) {
    const row = db.serviceRequests.find(item => item.id === req.params.id);
    if (!row) return res.status(404).json({ error: 'Service request not found.' });
    Object.assign(row, changes, { admin_response: changes.admin_response ?? row.admin_response, updatedAt: changes.updated_at });
    audit(req, 'passenger_service_request.updated', 'passenger_service_request', row.id, changes);
    return res.json({ data: row, simulated: true });
  }
  try {
    const rows = await update('passenger_service_requests', `id=eq.${encodeURIComponent(req.params.id)}`, { ...changes, changed_by: req.user.id });
    if (!rows?.length) return res.status(404).json({ error: 'Service request not found.' });
    await insert('audit_logs', { actor_id: req.user.id, action: 'passenger_service_request.updated', entity_type: 'passenger_service_request', entity_id: req.params.id, metadata: changes });
    res.json({ data: rows[0], simulated: false });
  } catch (error) { repositoryFailure(res, error); }
});

app.use('/api', (error, _req, res, _next) => { console.error(error); res.status(500).json({ error: 'Unexpected server error' }); });
app.listen(process.env.PORT || 4000, () => { console.log(`SkyFlow API listening on ${process.env.PORT || 4000}`); if (!supabaseConfigured && !demoMode) console.warn('Supabase is not configured; authentication and persistent production workflows are disabled.'); });
export default app;
